package io.github.testlens.migration.tooling;

import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class MigrationGitIsolationServiceTest {
    @TempDir Path temp;
    @Test void createsBranchFromExactCommitOnlyWithCapabilityAndNeverSwitches()throws Exception{Fixture f=fixture("branch");Path hookSentinel=temp.resolve("branch-hook");Path hook=f.repo.resolve(".git/hooks/post-checkout");Files.writeString(hook,"#!/bin/sh\nprintf hook > '"+slash(hookSentinel)+"'\n",StandardCharsets.UTF_8);hook.toFile().setExecutable(true);String original=gitText(f.repo,"branch","--show-current"),head=f.inspected.preflight().head().commit();var denied=new MigrationGitIsolationService().createBranch(f.inspected,f.checkpoint,f.store,"migration/denied",head,MigrationAuthorization.of("host"));assertEquals(MigrationGitIsolationAction.Status.SAFE_STOP,denied.status());var applied=new MigrationGitIsolationService().createBranch(f.inspected,f.checkpoint,f.store,"migration/approved",head,MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_BRANCH));assertEquals(MigrationGitIsolationAction.Status.APPLIED,applied.status());assertEquals(head,gitText(f.repo,"rev-parse","refs/heads/migration/approved"));assertEquals(original,gitText(f.repo,"branch","--show-current"));assertFalse(Files.exists(hookSentinel),"branch ref creation must not invoke post-checkout");var exists=new MigrationGitIsolationService().createBranch(new MigrationGitService().inspect(f.repo),readCheckpoint(f.store,applied.afterCheckpointRef()),f.store,"migration/approved",head,MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_BRANCH));assertEquals(MigrationGitIsolationAction.Reason.BRANCH_ALREADY_EXISTS,exists.reasons().get(0));assertFalse(new MigrationGitService().validBranchCandidate(f.repo,"bad..branch"));}
    @Test void worktreeRequiresSeparateRepositoryHelperApprovalAndValidatesCreatedState()throws Exception{Fixture f=fixture("worktree");Path destination=temp.resolve("new worktree");MigrationAuthorization ordinary=MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_BRANCH,MigrationAuthorization.Capability.CREATE_WORKTREE);var stopped=new MigrationGitIsolationService().createWorktree(f.inspected,f.checkpoint,f.store,destination,"migration/worktree",f.inspected.preflight().head().commit(),ordinary);assertEquals(MigrationGitIsolationAction.Reason.REPOSITORY_HELPER_APPROVAL_REQUIRED,stopped.reasons().get(0));assertFalse(Files.exists(destination));MigrationAuthorization full=MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_BRANCH,MigrationAuthorization.Capability.CREATE_WORKTREE,MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS);var applied=new MigrationGitIsolationService().createWorktree(f.inspected,f.checkpoint,f.store,destination,"migration/worktree",f.inspected.preflight().head().commit(),full);assertEquals(MigrationGitIsolationAction.Status.APPLIED,applied.status(),applied.toString());assertTrue(Files.exists(destination.resolve("tracked.txt")));assertEquals("migration/worktree",new MigrationGitService().inspect(destination).preflight().head().branch());Path collision=temp.resolve("collision");Files.createDirectory(collision);var collided=new MigrationGitIsolationService().createWorktree(new MigrationGitService().inspect(f.repo),f.checkpoint,f.store,collision,"migration/collision",f.inspected.preflight().head().commit(),full);assertEquals(MigrationGitIsolationAction.Reason.WORKTREE_DESTINATION_EXISTS,collided.reasons().get(0));}
    @Test void exactOidStashTracksScopeRestoresWithoutPopOrDropAndStopsOnChangedState()throws Exception{Fixture f=fixture("stash");Files.writeString(f.repo.resolve("tracked.txt"),"dirty");Files.writeString(f.repo.resolve("space unicode-żą.txt"),"new");var dirty=new MigrationGitService().inspect(f.repo);MigrationCheckpoint dirtyCp=checkpoint(dirty,f.store);MigrationAuthorization create=MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_STASH,MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS);var tracked=new MigrationGitIsolationService().createStash(dirty,dirtyCp,f.store,MigrationGitIsolationAction.StashScope.TRACKED_ONLY,create);assertEquals(MigrationGitIsolationAction.Status.APPLIED,tracked.status());assertTrue(Files.exists(f.repo.resolve("space unicode-żą.txt")));assertEquals("base",Files.readString(f.repo.resolve("tracked.txt")));String exact=tracked.stashRecord().stashOid();assertEquals(exact,gitText(f.repo,"rev-parse","refs/stash"));MigrationCheckpoint post=readCheckpoint(f.store,tracked.afterCheckpointRef());var restored=new MigrationGitIsolationService().restoreStash(new MigrationGitService().inspect(f.repo),post,f.store,tracked.stashRecord(),MigrationAuthorization.of("host",MigrationAuthorization.Capability.RESTORE_STASH,MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS));assertEquals(MigrationGitIsolationAction.Status.APPLIED,restored.status());assertEquals("dirty",Files.readString(f.repo.resolve("tracked.txt")));assertEquals(exact,gitText(f.repo,"rev-parse","refs/stash"),"apply must not pop/drop exact stash");Files.writeString(f.repo.resolve("tracked.txt"),"later");var changed=new MigrationGitService().inspect(f.repo);MigrationCheckpoint changedCp=checkpoint(changed,f.store);var stopped=new MigrationGitIsolationService().restoreStash(changed,changedCp,f.store,tracked.stashRecord(),MigrationAuthorization.of("host",MigrationAuthorization.Capability.RESTORE_STASH,MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS));assertEquals(MigrationGitIsolationAction.Reason.STASH_RESTORE_PRECONDITION_FAILED,stopped.reasons().get(0));}
    @Test void trackedAndUntrackedStashUsesNewExactOidEvenWhenAnotherStashExists()throws Exception{Fixture f=fixture("stash-untracked");Files.writeString(f.repo.resolve("tracked.txt"),"first");git(f.repo,"stash","push","-m","existing");String old=gitText(f.repo,"rev-parse","refs/stash");Files.writeString(f.repo.resolve("tracked.txt"),"second");Files.writeString(f.repo.resolve("untracked space.txt"),"u");var before=new MigrationGitService().inspect(f.repo);MigrationCheckpoint cp=checkpoint(before,f.store);var result=new MigrationGitIsolationService().createStash(before,cp,f.store,MigrationGitIsolationAction.StashScope.TRACKED_AND_UNTRACKED,MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_STASH,MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS));assertEquals(MigrationGitIsolationAction.Status.APPLIED,result.status());assertNotEquals(old,result.stashRecord().stashOid());assertFalse(Files.exists(f.repo.resolve("untracked space.txt")));MigrationCheckpoint post=readCheckpoint(f.store,result.afterCheckpointRef());var restore=new MigrationGitIsolationService().restoreStash(new MigrationGitService().inspect(f.repo),post,f.store,result.stashRecord(),MigrationAuthorization.of("host",MigrationAuthorization.Capability.RESTORE_STASH,MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS));assertEquals(MigrationGitIsolationAction.Status.APPLIED,restore.status());assertTrue(Files.exists(f.repo.resolve("untracked space.txt")));assertEquals(result.stashRecord().stashOid(),gitText(f.repo,"rev-parse","refs/stash"));}
    @Test void worktreeCheckoutHelpersExecuteOnlyBehindExplicitCapability()throws Exception{Fixture f=fixture("helpers");Path hookSentinel=temp.resolve("hook-sentinel"),filterSentinel=temp.resolve("filter-sentinel");Path hook=f.repo.resolve(".git/hooks/post-checkout");Files.writeString(hook,"#!/bin/sh\nprintf hook > '"+slash(hookSentinel)+"'\n",StandardCharsets.UTF_8);hook.toFile().setExecutable(true);Path helper=temp.resolve("smudge.sh");Files.writeString(helper,"#!/bin/sh\nprintf filter > '"+slash(filterSentinel)+"'\ncat\n",StandardCharsets.UTF_8);helper.toFile().setExecutable(true);git(f.repo,"config","filter.migration-smudge.smudge",slash(helper));Files.writeString(f.repo.resolve(".gitattributes"),"tracked.txt filter=migration-smudge\n");git(f.repo,"add",".gitattributes");git(f.repo,"commit","-m","filters");var state=new MigrationGitService().inspect(f.repo);MigrationCheckpoint cp=checkpoint(state,f.store);Path deniedPath=temp.resolve("denied helpers");var denied=new MigrationGitIsolationService().createWorktree(state,cp,f.store,deniedPath,"migration/helpers-denied",state.preflight().head().commit(),MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_BRANCH,MigrationAuthorization.Capability.CREATE_WORKTREE));assertEquals(MigrationGitIsolationAction.Status.SAFE_STOP,denied.status());assertFalse(Files.exists(hookSentinel));assertFalse(Files.exists(filterSentinel));Path allowedPath=temp.resolve("allowed helpers");var allowed=new MigrationGitIsolationService().createWorktree(state,cp,f.store,allowedPath,"migration/helpers-allowed",state.preflight().head().commit(),MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_BRANCH,MigrationAuthorization.Capability.CREATE_WORKTREE,MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS));assertEquals(MigrationGitIsolationAction.Status.APPLIED,allowed.status(),allowed.toString());Assumptions.assumeTrue(Files.exists(hookSentinel)||Files.exists(filterSentinel),"Current Git checkout did not invoke configured post-checkout/smudge fixture");assertTrue(Files.exists(hookSentinel),"post-checkout hook behavior changed");assertTrue(Files.exists(filterSentinel),"smudge filter behavior changed");}
    @Test void stashCleanFilterIsBehindRepositoryHelperCapability()throws Exception{Fixture f=fixture("stash-filter");Path sentinel=temp.resolve("stash-clean-filter");Path helper=temp.resolve("clean-filter.sh");Files.writeString(helper,"#!/bin/sh\nprintf clean > '"+slash(sentinel)+"'\ncat\n",StandardCharsets.UTF_8);helper.toFile().setExecutable(true);git(f.repo,"config","filter.migration-clean.clean",slash(helper));Files.writeString(f.repo.resolve(".gitattributes"),"tracked.txt filter=migration-clean\n");git(f.repo,"add","--all");git(f.repo,"commit","-m","clean-filter");Files.deleteIfExists(sentinel);Files.writeString(f.repo.resolve("tracked.txt"),"dirty");var state=new MigrationGitService().inspect(f.repo);Files.deleteIfExists(sentinel);MigrationCheckpoint cp=checkpoint(state,f.store);var denied=new MigrationGitIsolationService().createStash(state,cp,f.store,MigrationGitIsolationAction.StashScope.TRACKED_ONLY,MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_STASH));assertEquals(MigrationGitIsolationAction.Reason.REPOSITORY_HELPER_APPROVAL_REQUIRED,denied.reasons().get(0));assertFalse(Files.exists(sentinel));var applied=new MigrationGitIsolationService().createStash(state,cp,f.store,MigrationGitIsolationAction.StashScope.TRACKED_ONLY,MigrationAuthorization.of("host",MigrationAuthorization.Capability.CREATE_STASH,MigrationAuthorization.Capability.ALLOW_REPOSITORY_GIT_HELPERS));assertEquals(MigrationGitIsolationAction.Status.APPLIED,applied.status());assertTrue(Files.exists(sentinel),"Git 2.55 stash push should invoke the configured clean filter");}
    @Test void mutationDispatcherIsClosedAndEnvironmentDoesNotDisableRequiredLocks()throws Exception{assertEquals(java.util.Set.of("VERIFY_COMMIT","BRANCH_EXISTS","CREATE_BRANCH","WORKTREE_ADD","STASH_REF","STASH_CREATE_TRACKED","STASH_CREATE_UNTRACKED","STASH_APPLY"),java.util.Arrays.stream(MigrationGitIsolationService.MutationOperation.values()).map(Enum::name).collect(java.util.stream.Collectors.toSet()));assertFalse(MigrationGitIsolationService.mutationEnvironment().containsKey("GIT_OPTIONAL_LOCKS"));String source=Files.readString(Path.of("src/main/java/io/github/testlens/migration/tooling/MigrationGitIsolationService.java"));for(String forbidden:List.of("reset","clean","restore","checkout","switch","commit","merge","rebase","fetch","pull","stash pop","stash drop"))assertFalse(source.contains("\""+forbidden+"\""));assertFalse(java.util.Arrays.stream(MigrationGitIsolationService.MutationOperation.values()).anyMatch(x->x.name().equals("PUSH")));assertFalse(source.contains("cmd /c"));assertFalse(source.contains("powershell"));assertFalse(source.contains("sh -c"));}
    private Fixture fixture(String name)throws Exception{Path repo=temp.resolve(name);Files.createDirectory(repo);git(repo,"init");git(repo,"config","user.email","test@example.invalid");git(repo,"config","user.name","Test");Files.writeString(repo.resolve("tracked.txt"),"base");git(repo,"add","--all");git(repo,"commit","-m","base");MigrationGitService service=new MigrationGitService();var inspected=service.inspect(repo);Path state=temp.resolve(name+"-state");Files.createDirectory(state);MigrationStateStore store=MigrationStateStore.resolve(service,inspected,state);MigrationCheckpoint cp=checkpoint(inspected,store);return new Fixture(repo,inspected,store,cp);}private static MigrationCheckpoint checkpoint(MigrationGitService.Result r,MigrationStateStore store)throws Exception{MigrationCheckpoint cp=MigrationCheckpoint.create(r.preflight(),r.sourceState(),MigrationCheckpoint.Configuration.create(MigrationIsolationPlan.Choice.CREATE_DEDICATED_WORKTREE,MigrationCheckpoint.IntendedMode.BASELINE_PREPARATION,store.storage()),List.of(),null,null);store.write(cp);return cp;}private MigrationCheckpoint readCheckpoint(MigrationStateStore store,String ref)throws Exception{return store.read(Files.walk(store.root()).filter(p->p.getFileName().toString().equals(ref.replace(':','-')+".json")).findFirst().orElseThrow());}
    private static void git(Path p,String...args)throws Exception{List<String>c=new ArrayList<>();c.add("git");c.addAll(List.of(args));Process x=new ProcessBuilder(c).directory(p.toFile()).redirectErrorStream(true).start();String output=new String(x.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(x.waitFor()!=0)throw new AssertionError("git failed "+String.join(" ",args)+"\n"+output);}private static String gitText(Path p,String...args)throws Exception{List<String>c=new ArrayList<>();c.add("git");c.addAll(List.of(args));Process x=new ProcessBuilder(c).directory(p.toFile()).redirectErrorStream(true).start();String output=new String(x.getInputStream().readAllBytes(),StandardCharsets.UTF_8).strip();assertEquals(0,x.waitFor(),output);return output;}private static String slash(Path p){return p.toAbsolutePath().toString().replace('\\','/').replace("'","'\\''");}private record Fixture(Path repo,MigrationGitService.Result inspected,MigrationStateStore store,MigrationCheckpoint checkpoint){}
}
